import argparse
import csv
import sys


def count_nonempty(path):
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None:
            return [], {}
        counts = {name: 0 for name in reader.fieldnames}
        total = 0
        for row in reader:
            total += 1
            for name in counts:
                value = row.get(name)
                if value is not None and value.strip() != "":
                    counts[name] += 1
    return list(counts), counts, total


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file")
    args = parser.parse_args()

    try:
        names, counts, total = count_nonempty(args.csv_file)
    except OSError as exc:
        sys.exit(f"读取失败: {exc}")

    if not names:
        sys.exit("文件为空或没有表头")

    width = max(len(n) for n in names)
    print(f"{'列名'.ljust(width)}  非空值  总行数")
    for name in names:
        print(f"{name.ljust(width)}  {str(counts[name]).rjust(5)}  {total}")


if __name__ == "__main__":
    main()
